import React from 'react';
import { useExpenseSplit } from '../hooks/useExpenseSplit';

const TripSummary = ({ families, expenses }) => {
  const { totalAmount, perPerson, summary } = useExpenseSplit(families, expenses);

  const styles = {
    container: { marginTop: '20px', padding: '10px', border: '1px solid #ccc' },
    heading: { fontWeight: 'bold', fontSize: '18px', marginBottom: '10px' },
    item: { marginBottom: '6px' }
  };

  return (
    <div style={styles.container}>
      <div style={styles.heading}>Trip Summary</div>
      <p>Total Expense: ₹{totalAmount.toFixed(2)}</p>
      <p>Per Person Share: ₹{perPerson.toFixed(2)}</p>
      <h4>Settlements:</h4>
      {summary.length > 0 ? (
        summary.map((entry, idx) => (
          <div key={idx} style={styles.item}>
            {entry.from} should pay ₹{entry.amount.toFixed(2)} to {entry.to}
          </div>
        ))
      ) : (
        <p>All expenses are settled!</p>
      )}
    </div>
  );
};

export default TripSummary;
